style.css:
@-moz-document url-prefix("https://kubikhd.site/catalog/") {
body a {
    color: #ffffff;
    text-decoration: none;
}

body {
    background: #222328;
}

.block {
    display: none !important;
}

#maincol {
    width: 98%;
}

#content {
    background: #222328;
    padding: 10px 18px;
    background-size: 100% 1px;
}

#content-inside {
    width: 100%;
}

#container {
    width: 90%;
}

.allEntries .block {
    display: none !important;
}

.eTitle {
    font: 22px 'Tahoma';
    color: #ffffff;
    background: #222328;
    padding: 8px 10px 5px 10px;
}

table.eBlock > tbody> tr > td.eText > div > iframe {
    width: 90%;
    height: 600px !important;
}

html > body > div > div > div > div > div > div > table:not(.eBlock) {
    display: none !important;
}

 .uForm {
    display: none !important;
}

#footer {
    height: 80px;
}

.ya-share2, .ya-share2 * {
    display: none !important;
}
}
